    internal partial class GlobalBinaryCreateTranslation : Fallout76MajorRecordBinaryCreateTranslation
    {
        public new static readonly GlobalBinaryCreateTranslation Instance = new GlobalBinaryCreateTranslation();

        public override RecordType RecordType => throw new ArgumentException();
        public static ParseResult FillBinaryRecordTypes(
            IGlobalInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.XALG:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.XALG = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Global_FieldIndex.XALG;
                }
                case RecordTypeInts.FTAG:
                {
                    item.FormTags.SetTo(
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<String>.Instance.Parse(
                            reader: frame,
                            triggeringRecord: translationParams.ConvertToCustom(RecordTypes.FTAG),
                            transl: StringBinaryTranslation.Instance.Parse));
                    return (int)Global_FieldIndex.FormTags;
                }
                case RecordTypeInts.FNAM:
                {
                    return GlobalBinaryCreateTranslation.FillBinaryTypeCharCustom(
                        frame: frame.SpawnWithLength(frame.MetaData.Constants.SubConstants.HeaderLength + contentLength),
                        item: item,
                        lastParsed: lastParsed);
                }
                default:
                    return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
        }

        public static partial ParseResult FillBinaryTypeCharCustom(
            MutagenFrame frame,
            IGlobalInternal item,
            PreviousParse lastParsed);

    }

